  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (285::BIGINT, 'Este profe no lo recomiendo, usa mucha terminología avanzada en las primeras clases, que son en las que uno va empezando. Además, es incomprensible la forma en la que califica, es medio bipolar en lo que se puede hacer y no durante los proyectos. No lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b07b54f68d6391080bba3efe689e56a39cacd13a6a645cabd887a6e6de8ab010'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Desde mi opinión no le recomiendo matricular con él. Es muy poco comprensible y en mi opinión no explica bien, usa términos muy avanzados para alguien que esta empezando. Hace quices todas las semanas y son bastante tediosos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, '9db03c09168a820aa90aceaea17cc2345828a04284652d9b5ff082bd7c5f0353'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Un profe regular, ni muy bueno ni muy malo. Importante revisar el correo porque deja muchas clases asincrónicas o virtuales. El curso y los quices son fáciles pero requieren de poner atención en clase. Lo que si demanda bastante tiempo y es dificil son sus proyectos.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2025-03-12T00:00:00+00:00'::TIMESTAMPTZ, '3e8c24c5a56f41b8b9d14c1d2701af465761215a661eed73bc7f44d6b88638a0'::TEXT, ARRAY[2517]::BIGINT[]),
    (285::BIGINT, 'El profe es bueno, si va a consulta el evacua sus dudas, respecto a las clases las primeras semanas se presentaba luego cancelaba algunas clases, yo lo recomiendo pero tenga en cuenta que se puede atrasar en las califaciones y en entregas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'eb832d00a33d3e145e50dcbd289551d471d148346dbeb45b15a120d0ebbac156'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'El profesor es bueno a principio del semestre, luego se la pasa "afonico". Deja muchas cosas para el final, se atraso con una tarea que asigno hasta semana 20. Ademas nunca responde los correos. El curso no tiene tanta dificultad, pero yo lo pensaria 2 veces para matricular con el.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'aeea93433465cd10f7161704e8775265597ad8ca619fba0b2e228d530851ab68'::TEXT, ARRAY[2512]::BIGINT[]),
    (285::BIGINT, 'Al inicio muy bien, pero después empezó a faltar demasiado. A veces no abre el espacio para entregar trabajos en el tecDigital a tiempo y por eso uno puede perder puntos y no le importa si fue culpa de el. Postergo mucho la asignación de tareas dándonos muy poco tiempo para entregar 2.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'cb93960dc0965d7215ccdae7187287da2a10ec07a3a2790d11202b8bc8e12345'::TEXT, ARRAY[2512]::BIGINT[]),
    (285::BIGINT, 'Este profesor da clases la primera mitad del semestre, después se pasa poniendo la clase asincrónica y dejando laboratorios semanales, básicamente no hace nada. El curso es muy fácil, lo que demanda más tiempo son los proyectos pero son sencillos. Uno elige si aprender o no, igual pasa el curso.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'cb835c5618302d94df196b63f89337358fe6cb4f6b66043c17a9aa5faa69d673'::TEXT, ARRAY[2517]::BIGINT[]),
    (285::BIGINT, 'Es buen profe solo al inicio de semestre, se la pasa enfermo y nos atrasamos un montón nos tocó hacer 2 examenes seguidos además de que no vimos toda la materia, por cierto se la pasa afónico es su mayor excusa. No recomido este profesor.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-10-25T00:00:00+00:00'::TIMESTAMPTZ, '5a974f3626d5a430802012f3d1dfa4425133cf873577dd07e3d9ff04c86051fe'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Al principio es organizado. Toma mucho en cuenta la participación. No da puntos extra. Perdimos muchas clases y eso nos afectó al final del semestre porque no íbamos al corriente con los temas y demás grupo. Toma asistencia siempre.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'be1c661a6b68174580d294d8832b9d07ba6c12bb3f11a7cd701856cb9b678b2f'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Si busca profe ATI para llevar Intro a la progra, no dude en matricular con Luis Pablo. Es por mucho el mejor de los que ofrecen el curso. Tiene un manejo excelente de la teoría y la práctica. Los quices son complejos, pero le preparan para los exámenes (que son los mismos para todos los grupos).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '6013ac32d2af1e558f629ba1af1c918f1e73f57720e48f175c9bc6b9a304bdf6'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Es buen profe, respetuoso y comprensivo. El asistente que tuvo al menos este semestre era el problema. El profe un poco lerdo entregando los resultados de laboratorios, quices y proyectos. Se termina el curso en semana 19'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9aea17173cc456e1364a6e150e2a0ede914bb895a0f5d5b9cbd7c06b84ea0854'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Muy buen profesor, explica muy bien los conceptos en clase, se nota que sabe mucho sobre la materia y hace que las clases sean muy prácticas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b239e56c894df823741192720c9cb19cb8085fe04d7e4d42905416f84a90b07d'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Muy buen profe ,explica muy bien los temas. Se lo recomiendo demasiado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '66bb36db0ec329b313c098759904b525f6e0f5bf0aebcebcdb4b1163206d641c'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-05-13T00:00:00+00:00'::TIMESTAMPTZ, '9845084e8b565bf7e7b2f26fc791aa32283aaa570fdf9bccb37f5a70b21b3d98'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Explica bien la clases teoricas y practicas, solo que deja todo para el final y no mucha retroalimentacion durante el curso, es facil pasar con solo ir a clases.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2023-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'a3b4f4f3863ed4e8e2850ce3b2391fde06553a8d44319efe514bd07e8299f58e'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Pros: Es de los mejores profes de ATI cuando se refiere a explicar sobre los cursos de programación, hace bastantes laboratorios guiados que ayudan bastante, es comprensivo. Contras: Recicla muy rajado los materiales de años pasados. Deja todo para el final. Cancela clases el mismo día.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '415779b3711b797c29f3dbf7fb55671b362b677bf804e3b38ac812d0ef24b00b'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'Hay que hacer los labs realmente, las clases son sumamente teoricas para un curso que es muy practico. Escojan bien a su pareja y grupo, porque los trabajos son muy largos y no tan faciles.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3d1567c9514044d3dceca9e40cf59d57c3bc6663045c21a9c8eb1e905f8a53ce'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Muy decepcionante, no daba clases y las pocas que daba solo exponiendo pasábamos, en clases solo veia partidos, mejor hubiera puesto grabaciones de otros profes durante la clase, califica duro. Una prueba en semana 19 que vale 15% del curso, la verdad no lo recomiendo para este curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd81fda960cd229f765a07dee6063ed8729192fec917e1473f4b0ff86da03591b'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'Sumamente desorganizado, poco interés en el curso y los estudiantes. Casi todo el curso asincrónico y aún así los proyectos muy complejos. No responde correos y extendió el curso hasta S.19 con el proyecto y examen final (que lo puso a las 7PM!!) todo esto ya nosotros agotados y vale 40% de la nota.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8b4a18dd76dbb6f5c69cef6c4bd00d10ca54766675e32dad15e83d6aac55905d'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'El profe es muy bueno explicando, solo que cuesta que de retroalimentación, mejor lleve con Néstor pero sino este profe es decente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '704f6b6154e0ca009923245cbf5fdab75e6103aa2da813ba1a9abb824e568866'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Buen profesor, Explica con ejemplos y va programando en vivo en la clase. ayuda para entender el lenguaje. Pero, muchisimas tareas, laboratorios y asi. Las clases teoricas no son tan buenas como antes. ha bajado la calidad'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'a965e4fb3c9dadfa4763c3c804d20599c8e8f356864631234e0187739154a359'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Mae, Luis Pablo ha bajado la calidad de enseñanaza demasiado, muchas clases virtuales inecesarias, sus explicaciones no funcionan, los últimos temas lo explico en chino, para los proyecto le mete una complejidad increíble, me decepcionó muho, mantiene lo lerdo que es para revisar =('::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'e8fcacfc043bcd0bbad1590f377bd57a4143254685a90ba2743de872a683ac29'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'Si ud nunca ha tocado Java o no sabe que es POO. No lo lleve con él, nunca te va a explicar nada en clases, todo son trabajos que deja cada semana y cancela clases cuando le da la gana y te deja más trabajos porque sí. Si lo que quiere es pasar el curso está bien, pero no va a aprender nada.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f926871357f6075eaf4b95241d8ff87ef7fbacb8d2c5fcedf815dfec06221916'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'El profesor en términos generales es bueno. Explica la materia bien y está anuente a las dudas. Sin embargo, en cuanto a evaluaciones en ocasiones no hay claridad de los que se evalúa y entonces califica bajo. Creo que también es cuestión del asistente.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2c0e2168c95f89ca6d0e5b38c09a3f0de984942b6545f9135ccf3cd65766ec3b'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'El profe explica bien, sin embargo los proyectos son muy largos y complejos, además deja en todas las clases mínimo una tarea, se enoja fácilmente con los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0850a4012aa952ed3bfd752f09ac7743b74a0ffe01da5de597bd8e0231dbb713'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'En lo personal no tenia ningún conocimiento en programación, el es muy bueno explicando se preocupa por que uno entienda, eso si prepararse porque deja mucho laboratorio y tareas'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0ec68cd84bdc4502e3e446fabed6508319b58c4e43d520cd0db771a91789e455'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Entrega (si acaso) casi todas las notas al final del semestre, no explica lo que uno falla. Casi en todas las clases pone un video. Honestamente, no lo recomendaría. Es muy fácil fallar puesto que no entrega nada y uno no sabe en que fallo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'ff6db78c4da6fe0e5ab62f36371ce6f54510ec0ad58788fbad7fd117085c9fd7'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'El tipo grita de la nada, es explosivo y no acepta opiniones diferentes a la suya.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '7ba96c5bbed3bb1ad5b34b95864ccd7246529aeed2913505e81f6abc5dcb502e'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Pregunta si alguien tiene dudas antes de seguir avanzando,explica la materia claramente,caso contrario en las instrucciones de los trabajos,recomiendo que pregunten y la investigación es parte de la carrera,dura meses revisando todo lo que los asistentes no revisan,sigan instrucciones es muy radical'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a13d612aca7f66a7faa9da7268ead4970c02d5471898b75e8a566dd2570c374f'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Desde la virtualidad es pésimo, siempre pone clases grabadas y deja de dar lecciones sincrónicas como en semana 14, el resto son asincrónicas Dura mil años para dar notas de exámenes y trabajos. Los proyectos son totalmente distintos a lo que se ve en clase según el "investigación"'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, '0d4c1843a84fc5f47ec858572f4b037c45fe58158df6a8510b80075a408ef343'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Sinceramente el profe no está mal, el problema es que si se llega a pegar con algo que está explicando pierde el rumbo y lo termina dejando a medias. Por lo que, es muy temperamental. Siempre va a creer que tiene la razón, por lo que una discusión con él se puede volver eterna.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '49976f9ffac4d5befe04e5a81f25f9474332608b4986ced8b058635b4a0afdd4'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Pésimo, es un profesor temperamental y explosivo. No acepta opiniones diferentes a las de él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'cedac88186f0efa0d98a4f376d4156d4cbd09d35d8ffbefa55fb0778dac55f1b'::TEXT, ARRAY[2543]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos exámenes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0901738c5fa3120363b5e3ac4191c22e37121601f88cc5f9360a71d03392f6bc'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'En semestre virtual fue muy organizado deja muchas tareas eso si hay que estar muy pendiente y muchos examenes pequeños para evaluar todo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'e02d1f98874215416226cc437fd83287e54583f67fd466f763b75ee7c289980c'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Es un 100 de profe. Explicó demasiado bien y entendí todo. Yo no sabia nada de programación y siento que me lo enseño todo excelente. Si tarda un poco en subir los resultados de las evaluaciones. Pero en serio si puede, matriculen con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '8be27f590a37bbd9739c1be7047fa29fad4fd86381d21896f558ef4cc8c05684'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'b9fd94f2feb89d85c072573f4eb3676beb06078622ef223d29423f5bede4bdb3'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Al menos en clases virtuales brinda un minimo apoyo. Las clases asincronicas son bastante molestas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-06-02T00:00:00+00:00'::TIMESTAMPTZ, '30c3cb8d619fbd8ffd445594b6ff505a8486399c0facf50317f568c07126ecd2'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'El profe es muy desordenado para todo sabe explicar y dura mucho pero mucho para entregar los exámenes y las progras las deja muy seguidas la primera la deja en semana 12, poco tiempo pero no imposible y es muy duro a la hora de calificar o tienes todo o nada'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2019-12-06T00:00:00+00:00'::TIMESTAMPTZ, '88afe9afb1b58d1a256ccd73531391f16f146891816cebf275fc5d20df8f7847'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'NO Hizo berrinche en la coordinación de ati para dar un curso que no pudo manejar, PÉSIMO, no sabe de la materia, canceló clases por gusto para al final reponer en semana 17. No le importa si el estudiante entiende o no.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e66dccc2f20eb764d93102010e34f4d1962dd05a4c2ab77beb87b14a6e4ae4f0'::TEXT, ARRAY[2543]::BIGINT[]),
    (285::BIGINT, 'Profe un toque desordenado, uno sabe si pasó o se quedó hasta el último momento del semestre. Es un toque exigente pero se aprende demasiado con él. Explica las veces que necesite.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'af2aecab1d39801599f92fa72fcb457960c7264c9f3195c412d7d039b5e1353e'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'Es un profe que deja mucho trabajo fuera de la clase, pero muchooo, a pesar de esto, uno aprende bastante debido a esto.El profe brinda la ayuda necesaria. Otro aspecto sobre el profe es que es algo desordenado para revisar evaluaciones y dura mucho tiempo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'f4902b0b809dd7e4008d06e4450823fe8f5075db7be226d94ed82a550a134fca'::TEXT, ARRAY[2523]::BIGINT[]),
    (285::BIGINT, 'Excelente profesor, se preocupa por sus estudiantes, las clases son excelentes, casi siempre deja laboratorios fáciles por lo cual se lleva la materia al día. Los proyectos son muy grandes y requieren mucho tiempo, pero nada que no se pueda lograr. Matricularía de nuevo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-01T00:00:00+00:00'::TIMESTAMPTZ, '5194a30f022f0da4deaa57660ab79342cf34fb2107c8a1a59dd7819acc356fa6'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Buen profe, los laboratorios son muy faciles, soló que los 3 proyectos que deja son dificiles y los utimos 2 proyectos da muy poco tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '04b099560141e5c57dfb708add4d714afeb033d0b826d5530052da4370abd6a3'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'a0e04cedc7c29d185c42bf7000275775061e180e992de1f5e4544935b0f62ab1'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Excelente profe, explica bien y muy buena nota. Lo único es que debes cumplir con lo que pide como obligatorio para las progras o tienes 0 xd'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, '012cbc5d404585e23bced4663ebcf66895e7a6e9033f617aa6482596879d217f'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Es un excelente profe , los proyectos son super largos y los exámenes son difíciles. Se aprende mucho , va a aprender todo sobre objectos y patrones de diseño'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2018-11-01T00:00:00+00:00'::TIMESTAMPTZ, 'c28cd2a01c883f282f91e818397e8f56192c9ace6ec1f3d1332544196f07a85e'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2018-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'ac861fab6b666eff0e44b2f69b08d32580ae7d87dd524052eda8d6eb43b98525'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Exámenes difíciles, califica súper rudo. Baja muchos puntos por cosas que no deberían valer tanto. Deja muchas tareas y laboratorios. Quita mucho tiempo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-10-04T00:00:00+00:00'::TIMESTAMPTZ, '7c208da47b018e459fce9770826e7fec9f97c6167586da0473e48c794a980736'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Muy buen profesor, ayuda mucho si hay dudas de materia o proyectos, pero las progras tienen almenos un elemento muuuy dificil que generalmente baja muchos puntos al proyecto o lo pone en cero. Examenes dificiles pero si se estudia bastante se sale bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0026364e251d93b39b08190ec1677589dd532aa852b2a3daa666ed6c5c4f8a55'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Muy buen profe para cursos introductorios. Deja programa vacilonas pero con instrucciones muy muy claras. Los exámenes son fáciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, '787878a7c71f8347c05ab275e41d9ad6148ab882525159bd83e598c0d8bafe70'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Deja trabajos largos, nada que no se pueda hacer pero se pueden tornar tedioso, materia aburrida pero es lo usual, laboratiorios una vez a la semana'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2018-01-10T00:00:00+00:00'::TIMESTAMPTZ, '91b9ba2d92ae13309bd37a05e51046b0a157724840797ced4b0d52e7c0d3bd4b'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Es excelente, deja la materia muy clara. Asegurese de hacer bien los laboratorios y que el note su interes en el ellos y en el curso en general y si pasa. Los examenes son muy faciles y apegados a los laboratorios y practicas de examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-12-28T00:00:00+00:00'::TIMESTAMPTZ, '06a7e72e52d3c3beda1c456e0e40364bb9cf07b773e73fa935f515d502722ecd'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'El profe es excelente, la clase aveces se hacen aburridas pero es por la materia. Progras algo largas pero se hacen si se les dedica el tiempo necesario. Se preocupa por el estudiante y distribuye bastante la nota. Da puntos extra'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'b6cee887fc9ce241e3080b9e0320d01f17c63be34e38b0bcc0c71710fa302014'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Es buen profe, deja la materia clara y se aprende bastante, a demás se interesa de que uno aprenda... Lo único malo es que la clase es demasiado aburrida, pero sí da lo justo y enseña bastante. Pasa lista en las clases, entonces hay que ir siempre.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '796b1e1ba9ebc0490c317e324ba22983fc993e604b2772d5e51041c9e9b26bd3'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Deja el curso botado y le ponen a Núñez, no se arriesgue'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2017-07-31T00:00:00+00:00'::TIMESTAMPTZ, '4496dd7d47fe91ede69cf7ae55950a9ee1724a042f8a78f4a665e0f3d82ec110'::TEXT, ARRAY[2527]::BIGINT[]),
    (285::BIGINT, 'Mientras se ponga atención la clase se pasa sola. Los exámenes son fáciles y generalmente incluyen aunque sea un ejercicio que ya se hizo en clase o en práctica para examen. El profe explica muy bien y se interesa por que uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a5c6e2d90153d4ea6f80effdd54bffc1ba410dc04056e539be47112cb080e070'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Explicaba bien y realiza muchos ejemplos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f72df8e24258a72321b1afd02873ad381bfd360c057358855cebf09a908692d9'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Es un gran profe; se preocupa de que sus estudiantes entiendan la materia y pasen los exámenes. Las progras son bastante largas pero eso es con todos los profes en taller. No es tan matado mientras se le dedique tiempo al curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1b95e5c49a19a021211ba295b690f8e7cb8122b54caa9019146dce0ac792a8a0'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Explica bien, los exámenes van acorde a lo visto en clase, el proyecto final es algo largo pero realizable, si le pone atención y hace las prácticas pasa el curso con buena nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1d825b2bc7abbc502f1267f43354a4781ed337f50bb1362505cea53c333f3ae7'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Un excelente profesor! Muestra interés por el aprendizaje, explica claro y da ejemplos sencillos de entender. Siempre dispuesto a ayudar a los estudiantes. Exámenes basados en las practicas que se hacen en clase. Se aprende mucho. Lo recomiendo 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'afa1acfce2da96511b4211541439789e9a9e5c44ba2e00387f8cacb6b13fe17c'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Muy buen profesor, lo recomiendo bastante. Se aprende y ayuda. Eso si el trabajo final que deja es muy grande, pero si se logra hacer.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ff26fd59d7f50eb1c132b7c0c9f07eec7b7da88e66529a1559ec993ed55d9021'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '8ed3b8e4023e7085cfeafd7bf4e05f23cf4fed530a1d56f4fc86d645cc8a9bf0'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'El profe es excelente. Se preocupa mucho por los estudiantes y explica bien la materia. En la 2nda y 3era progra hay que investigar DEMASIADO eso si asi que haganla con antelación. Los exámenes son realizables solo que sí tienen que practicar bastante y da puntos extra. En fin, el mejor profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '8e7e204139d1609828abf133524bd184fe0f096a8ac5f30ccf23011ef509cdd2'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Excelente profesor :) sumamente recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f5a1ca80c04dd306ed4448a4032246c0fe48c1b03cdb94b59a56eaabfb2bc8e4'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Muy buen profe ayuda mucho y explica bastante. Recomendando'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'd12058d0732b09bb0f0367f72986a6987a1146512e3ee1ba3d3cc358b651c2ee'::TEXT, ARRAY[2510, 2512, 2527]::BIGINT[]),
    (285::BIGINT, 'Se avanza lento pero se aprende mucho. Es muy paciente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '694fce2a8cedb1b83e093b263f46396de0640907bb50f47fc356b767220d56ee'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-10T00:00:00+00:00'::TIMESTAMPTZ, '4c128bc387258bdd2693cbfafcfc9e46649ab8a44b16098de90431ee60335191'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Explica excelente. Es un profesor justo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-25T00:00:00+00:00'::TIMESTAMPTZ, '5e16c6f9407430f5daa38ad0fa1354cfe130df5956f44998d8415c8fcce0f302'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Es un buen profe con los estudiantes, toma en cuenta la carga académica para las fechas de entrega y se preocupa por enseñar todo bien, un gran profe para aprender a programar!.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'defdcce40daf3c31b034977bfaabaa7355b7ee11b0ac4e0488d1219d5f763064'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Sinceramente no lo considero buen profe, para la primera parte del curso(antes del primer parcial) es bueno, pero en la segunda parte donde ya se ven temas un poco mas complejos lo que hace es ir haciendo una practica en el proyector y uno copia y luego tiene que ir a entender todo a la casa.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '35f39042b011a2c7441c8875e99197e716ce55651f5fbe13ca74deb7ca863ad5'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Súper paciente para explicar, tiene bastante pedagogía, y deja prácticas para los exámenes y se basa en ellas para hacer los exámenes. Califica un poco duro, pero lo hace porque explica demasiado bien. Solo que cuando se enoja, explota, pero se le pasa rápido.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b713e36fe3231dbe244002dce60b64779c476dd728dc958b5f74b52a4ccef48f'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Muy buen profe, bastante accesible y paciente con sus estudiantes, en especial si estos tienen deseos de aprender; Lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '75344efad5db681fd62a8bae8fd569b3c8e0fd1e4ca169f9e70a8197f95bd863'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Muy buen profesor. Siempre piensa en que es mejor para los estudiantes y que entiendan. En mi caso no hizo proyecto solo 3 exámenes a mano pero son similares a las practicas o laboratorios hechos en clase. Califica suave, 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e4a324624353fd396ebb99826fc66d9e09ca6be4fc2b86fac00d08478932fb0f'::TEXT, ARRAY[1249]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '03fdbe7256cdb987947947aed3cbe3b6ff85e37e38a95b21eb1197a2cbdc24ac'::TEXT, ARRAY[2510]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd2d2f9c85d0798d4f7bd44eb2b6884551e767a3cc9a4c570e5da80b1fb0f9632'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Buen profe, califica duro pero se aprende mucho, para las progras hay que investigar mucho eso si'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '322ac89ea330a530275c95d08f5a906dc5865008088d41c29c5f178e634bb9cb'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd5a426142dcda1a04720288f4f127d0727b8486efe89dcf1304bfe4736cca32e'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (285::BIGINT, 'Califica duro se aprende bastante'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '6befe16699622dfe4c35d97d10adb91ea5fb2f0a086d0a834dcff14cc3f5f825'::TEXT, ARRAY[2510, 2512]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
